from jsonb_to_recordset($json$[{"id":"che-pe-226","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fluorine outranks chlorine in electronegativity even though Cl has more protons, because the bonding pair in an F–X bond is","options":["farther from the F nucleus","much closer to the small, poorly shielded fluorine atom","held only by London forces","shared equally in every case"],"answer_index":1,"explanation":"Size and Zeff on the valence shell dominate χ; the extra protons of Cl are offset by an extra shielding shell.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-227","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Valence electrons of an atom are those present in its","options":["innermost shell","outermost shell","nucleus","neutron cloud"],"answer_index":1,"explanation":"Chemical valence is decided by the electrons in the highest principal shell.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-228","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Alkali metals exhibit a characteristic valence of","options":["one","two","three","seven"],"answer_index":0,"explanation":"Each atom has a single ns¹ electron, which it loses (or shares) in compounds.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-229","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Halogens commonly exhibit a valence of one, corresponding to the oxidation state","options":["+7 in every ionic salt","−1 in simple ionic compounds","+1 only","zero in all molecules"],"answer_index":1,"explanation":"Gain of one electron completes the octet and gives X⁻ (fluoride, chloride, …).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-230","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The characteristic oxidation state of alkali metals in their compounds is","options":["−1","+1","+2","+7"],"answer_index":1,"explanation":"Loss of the single valence electron leaves a noble-gas cation M⁺.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-231","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"For many p-block elements the highest oxidation state equals the","options":["number of neutrons","number of valence electrons (the old group number)","period number","mass number minus Z"],"answer_index":1,"explanation":"Group 15 can reach +5, group 16 +6 and group 17 +7 when all valence electrons are involved.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-232","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Carbon is tetravalent in the great majority of its stable compounds because it has","options":["two valence electrons","four valence electrons","six valence electrons","no valence electrons"],"answer_index":1,"explanation":"The 2s² 2p² set provides four electrons for four covalent bonds (as in CH₄).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-233","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Transition metals are noted for showing","options":["only the oxidation state +1","variable oxidation states","no cations at all","a unique oxidation state of −4"],"answer_index":1,"explanation":"Both ns and (n−1)d electrons can take part in bonding, so several OS are common.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-234","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In most of its compounds oxygen exhibits the oxidation state","options":["+2","−2","+6","0 only"],"answer_index":1,"explanation":"Oxygen is highly electronegative and usually completes its octet by gaining or sharing two electrons.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-235","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Nitrogen can show oxidation states ranging from −3 in ammonia to +5 in","options":["nitrogen gas","nitric acid","hydrazine","the nitride ion"],"answer_index":1,"explanation":"HNO₃ and nitrates use all five valence electrons of N; NH₃ uses the −3 state.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-236","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Manganese attains its highest oxidation state of +7 in the","options":["manganous ion Mn²⁺","permanganate ion","manganese metal","MnO solid only"],"answer_index":1,"explanation":"In MnO₄⁻ the seven 4s and 3d electrons of Mn are all involved in bonding.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-237","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Sulphur can show the +6 state in SO₃, whereas oxygen rarely exceeds −2, because sulphur has","options":["a smaller size than oxygen","vacant 3d orbitals","fewer valence electrons","no p orbitals"],"answer_index":1,"explanation":"The 3d orbitals of S allow expansion of the octet; second-period O cannot do this.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-238","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Chlorine exhibits odd positive oxidation states +1, +3, +5 and +7 in addition to","options":["+8","−1","−7","+2 only"],"answer_index":1,"explanation":"The −1 state is the halide; the odd positive states appear in oxoacids and oxides as 3s and 3p (and 3d) electrons are unpaired.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-239","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Group-14 elements typically form tetravalent compounds, matching","options":["two valence electrons","four valence electrons","six valence electrons","a noble-gas vacancy of one"],"answer_index":1,"explanation":"The valence configuration ns² np² supplies four electrons for four bonds (CCl₄, SiCl₄, …).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-240","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among the 3d metals, the highest oxidation state is +7, shown by manganese, equal to the total of its","options":["3p electrons only","4s and 3d electrons","4p electrons","neutrons in ⁵⁵Mn"],"answer_index":1,"explanation":"Mn is 4s² 3d⁵; using all seven electrons gives Mn(VII) as in KMnO₄. Iron does not reach +8 in ordinary compounds.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-241","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Metallic character of elements increases on moving","options":["across a period from left to right","down a group","from Cs to Li","from Na to Cl"],"answer_index":1,"explanation":"Size grows and IE falls down a group, so the atom loses electrons more readily.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-242","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Metallic character of elements decreases on moving from left to right across a","options":["group","period","set of isotopes","noble-gas family"],"answer_index":1,"explanation":"IE and electronegativity rise across a period, so electron loss becomes less favourable.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-243","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Metals tend to lose valence electrons and form","options":["anions","cations","noble-gas atoms of lower Z","free neutrons"],"answer_index":1,"explanation":"Electropositive behaviour is the chemical signature of metallic character.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-244","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Non-metals tend to gain electrons and form anions or","options":["metallic lattices","covalent molecules","only monatomic cations","bare nuclei"],"answer_index":1,"explanation":"High IE and high electronegativity favour electron gain or sharing rather than cation formation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-245","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Metalloids show a mixture of","options":["only ionic bonding","metallic and non-metallic properties","no electrical conductivity ever","f-block chemistry only"],"answer_index":1,"explanation":"Elements on the p-block staircase (B, Si, Ge, As, Sb, Te) are the usual metalloids.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-246","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In the third period the most metallic element is","options":["chlorine","silicon","sodium","argon"],"answer_index":2,"explanation":"Na stands at the left of period 3 and has the lowest IE of that row.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-247","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In the second period the most non-metallic element is","options":["lithium","carbon","fluorine","beryllium"],"answer_index":2,"explanation":"Fluorine has the highest electronegativity and a very high IE among the period-2 non-nobles.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-248","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The reducing power of alkali metals increases down the group, in parallel with","options":["ionisation enthalpy","metallic character","electronegativity","electron gain enthalpy becoming more negative"],"answer_index":1,"explanation":"The heavier alkali metal loses its ns¹ electron more easily and is therefore the stronger reductant.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-249","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Metallic character in the set Na, Mg, Al decreases from","options":["aluminium to sodium","sodium to aluminium","magnesium to sodium","aluminium to argon"],"answer_index":1,"explanation":"Across period 3 the atoms become smaller and harder to ionise, so metallic character falls Na > Mg > Al.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-250","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among Li, Na and K, potassium is the most metallic because it has the","options":["smallest size and highest IE","largest size and the lowest ionisation enthalpy","highest electronegativity","closed 3p⁶ valence shell"],"answer_index":1,"explanation":"Down group 1, size rises and IE falls, so K loses its 4s electron most readily of the three.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
